// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount1, uint256 amount2) public {
        vm.assume(actor != address(0));
        amount1 = bound(amount1, 0, 10 ether);
        amount2 = bound(amount2, 0, 10 ether);

        vm.deal(actor, amount1 + amount2);

        vm.prank(actor);
        c.addToBalance{value: amount1}();
        uint256 afterFirst = c.getBalance(actor);
        assertTrue(afterFirst == amount1);

        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: amount2}() { ok = true; } catch { ok = false; }

        assertTrue(ok && c.getBalance(actor) == afterFirst + amount2);
    }
}
